CREATE TABLE IF NOT EXISTS system_settings (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, value TEXT NOT NULL, value_type TEXT NOT NULL DEFAULT 'string', description TEXT, updated_by TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS whatsapp_messages (id TEXT PRIMARY KEY, member_id TEXT REFERENCES members(id), recipient_number TEXT NOT NULL, message_type TEXT NOT NULL, message_body TEXT NOT NULL, reference_type TEXT, reference_id TEXT, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, sent_at TEXT, last_error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO system_settings (id, key, value, value_type, description) VALUES ('setting-point-earn-rate', 'point.earn_rate', '10000', 'number', 'Rupiah transaksi per 1 point'), ('setting-point-conversion-rate', 'point.conversion_rate', '100', 'number', 'Nilai saldo untuk 1 point'), ('setting-deposit-min', 'deposit.min_amount', '10000', 'number', 'Minimal deposit');
CREATE INDEX IF NOT EXISTS idx_whatsapp_messages_status ON whatsapp_messages(status, created_at);
